/** The module a project's content API resolves to. Added only when it is reached for. */
export const CONTENT_MODULE_NAME = "pletivo-content.js";

/** The module `astro:i18n` resolves to. Added only when reached for. */
export const I18N_MODULE_NAME = "pletivo-i18n.js";

/** The module `astro:assets` and an `image()` schema resolve through. Added only when reached for. */
export const IMAGE_MODULE_NAME = "pletivo-image.js";

/** The protocol module shared by the host and the isolate entry. */
export const ISOLATE_PROTOCOL_MODULE_NAME = "pletivo-isolate-protocol.js";

/** The Loader's main module. Never a project path. */
export const ISOLATE_ENTRY_MODULE_NAME = "pletivo-entry.js";

/** The per-program data module the host generates; see `IsolateProgram` in isolate-entry.ts. */
export const ISOLATE_PROGRAM_MODULE_NAME = "pletivo-program.js";

/** The entry modules every Loader program carries next to its data module. */
export const ISOLATE_ENTRY_MODULES: Readonly<Record<string, string>> = {
  "pletivo-entry.js": GENERATED_MODULES["pletivo-entry.js"],
  "pletivo-isolate-entry.js": GENERATED_MODULES["pletivo-isolate-entry.js"],
};

/** The Tailwind isolate's request handling; exports `createTailwindEntry`. */
export const TAILWIND_ENTRY_MODULE_NAME = "pletivo-tailwind-entry.js";

/** Tailwind and its entry, which every Tailwind isolate program carries next to its plugins. */
export const TAILWIND_ISOLATE_MODULES: Readonly<Record<string, string>> = {
  "pletivo-tailwind.js": GENERATED_MODULES["pletivo-tailwind.js"],
  "pletivo-tailwind-entry.js": GENERATED_MODULES["pletivo-tailwind-entry.js"],
};
